    "}",
    "",
    "export default async function flow(",
    "  input: {",
    "    planPath: string;",
    "    artifactDir: string;",
    "    baseUrl: string;",
    "    viewportWidth: number;",
    "    viewportHeight: number;",
    "    suite: string;",
    "  },",
