    ") {",
    "  /* ---------------------------------------------------------------- */",
    "  /* 0 — the plan                                                      */",
    "  /* ---------------------------------------------------------------- */",
    "",
    "  const planFile = await tools.fs.readTextFile({ path: input.planPath });",
