    "        });",
    "      }",
    "",
    "      await tools.browser.tabs({ action: \"close\" });",
    "    }",
    "  } catch (runError) {",
    "    aborted = true;",
    "    abortReason = `${runError}`;",
    "",
    "    results.push({",
    "      id: input.suite,",
    "      status: \"error\",",
    "      detail: `the run itself failed: ${runError}`",
    "    });",
