    "    });",
    "  }",
    "",
    "  /* ---------------------------------------------------------------- */",
    "  /* 2 — verdict                                                       */",
    "  /* ---------------------------------------------------------------- */",
    "",
    "  if (aborted) {",
    "    return {",
